INSERT OR IGNORE INTO lessons (id, document_id, chapter, title) VALUES ('d12-b2', 'demo12-2026-v1', 'Chương II. Vectơ và tọa độ', 'Tọa độ của vectơ');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d10-b1:q001:r1', 'd10-b1', 1, 1, 'mcq', '<p>Cho ba điểm A, B, C. Tổng <math xmlns="http://www.w3.org/1998/Math/MathML"><mrow><mover accent="true"><mi>AB</mi><mo>→</mo></mover><mo>+</mo><mover accent="true"><mi>BC</mi><mo>→</mo></mover></mrow></math> bằng vectơ nào?</p>', '[{"key":"A","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>AC</mi><mo>→</mo></mover></math>"},{"key":"B","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>CA</mi><mo>→</mo></mover></math>"},{"key":"C","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>BA</mi><mo>→</mo></mover></math>"},{"key":"D","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>CB</mi><mo>→</mo></mover></math>"}]', '"A"', '<p>Áp dụng quy tắc ba điểm: vectơ AB + vectơ BC = vectơ AC.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d10-b1:q003:r1', 'd10-b1', 3, 1, 'mcq', '<p>Cho hình bình hành ABCD. Tổng vectơ AB và vectơ AD bằng vectơ nào?</p>', '[{"key":"A","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>BD</mi><mo>→</mo></mover></math>"},{"key":"B","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>AC</mi><mo>→</mo></mover></math>"},{"key":"C","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>CA</mi><mo>→</mo></mover></math>"},{"key":"D","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>DB</mi><mo>→</mo></mover></math>"}]', '"B"', '<p>Theo quy tắc hình bình hành, vectơ AB + vectơ AD = vectơ AC.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d10-b1:q007:r1', 'd10-b1', 7, 1, 'mcq', '<p>Hiệu <math xmlns="http://www.w3.org/1998/Math/MathML"><mrow><mover accent="true"><mi>AB</mi><mo>→</mo></mover><mo>−</mo><mover accent="true"><mi>AC</mi><mo>→</mo></mover></mrow></math> bằng vectơ nào?</p>', '[{"key":"A","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>BC</mi><mo>→</mo></mover></math>"},{"key":"B","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>CA</mi><mo>→</mo></mover></math>"},{"key":"C","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>CB</mi><mo>→</mo></mover></math>"},{"key":"D","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>BA</mi><mo>→</mo></mover></math>"}]', '"C"', '<p>Vectơ AB − vectơ AC = vectơ CB.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d10-b1:q012:r1', 'd10-b1', 12, 1, 'mcq', '<p>Vectơ nào sau đây luôn là vectơ không?</p>', '[{"key":"A","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>AB</mi><mo>→</mo></mover></math>"},{"key":"B","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>AC</mi><mo>→</mo></mover></math>"},{"key":"C","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>BC</mi><mo>→</mo></mover></math>"},{"key":"D","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>AA</mi><mo>→</mo></mover></math>"}]', '"D"', '<p>Vectơ có điểm đầu trùng điểm cuối là vectơ không.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d10-b1:q015:r1', 'd10-b1', 15, 1, 'tf', '<p>Xét các khẳng định sau với ba điểm A, B, C bất kỳ.</p>', '[{"key":"a","text":"Vectơ AB = −vectơ BA."},{"key":"b","text":"Vectơ AA là vectơ không."},{"key":"c","text":"Tổng vectơ AB và vectơ BA là vectơ không."},{"key":"d","text":"Vectơ AB + vectơ BC = vectơ AB."}]', '[true,true,true,false]', '<p>Ba khẳng định đầu đúng. Tổng vectơ AB và vectơ BC bằng vectơ AC, không phải luôn bằng vectơ AB.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d10-b2:q001:r1', 'd10-b2', 1, 1, 'mcq', '<p>Cho hai vectơ có độ dài 2 và 3, góc giữa chúng bằng 60°. Tích vô hướng bằng bao nhiêu?</p>', '[{"key":"A","text":"3"},{"key":"B","text":"6"},{"key":"C","text":"−3"},{"key":"D","text":"0"}]', '"A"', '<p>Tích vô hướng bằng 2 × 3 × cos 60° = 3.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d10-b2:q004:r1', 'd10-b2', 4, 1, 'mcq', '<p>Cho <math xmlns="http://www.w3.org/1998/Math/MathML"><mrow><mo>|</mo><mover accent="true"><mi>a</mi><mo>→</mo></mover><mo>|</mo><mo>=</mo><mn>5</mn></mrow></math>. Tích vô hướng của vectơ a với chính nó bằng bao nhiêu?</p>', '[{"key":"A","text":"5"},{"key":"B","text":"10"},{"key":"C","text":"25"},{"key":"D","text":"0"}]', '"C"', '<p>Vectơ a · vectơ a = |vectơ a|² = 25.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d10-b2:q008:r1', 'd10-b2', 8, 1, 'mcq', '<p>Hai vectơ khác vectơ không và vuông góc với nhau có tích vô hướng bằng bao nhiêu?</p>', '[{"key":"A","text":"1"},{"key":"B","text":"0"},{"key":"C","text":"−1"},{"key":"D","text":"Không xác định"}]', '"B"', '<p>Tích vô hướng bằng tích hai độ dài nhân cos 90° = 0.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d10-b2:q011:r1', 'd10-b2', 11, 1, 'short', '<p>Cho vectơ a = (1; 2), vectơ b = (3; −1). Tính a · b.</p>', '[]', '"1"', '<p>a · b = 1 × 3 + 2 × (−1) = 1.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d10-b2:q016:r1', 'd10-b2', 16, 1, 'tf', '<p>Cho vectơ a = (2; −1), vectơ b = (1; 2).</p>', '[{"key":"a","text":"a · b = 0."},{"key":"b","text":"Độ dài của vectơ a bằng √5."},{"key":"c","text":"a + b = (3; 1)."},{"key":"d","text":"a = b."}]', '[true,true,true,false]', '<p>a · b = 2 − 2 = 0; |a| = √5; a + b = (3; 1); hai vectơ khác nhau.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d11-b1:q001:r1', 'd11-b1', 1, 1, 'mcq', '<p>Giá trị của <math xmlns="http://www.w3.org/1998/Math/MathML"><mrow><mi>sin</mi><mfrac><mi>π</mi><mn>6</mn></mfrac></mrow></math> bằng</p>', '[{"key":"A","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mfrac><mn>1</mn><mn>2</mn></mfrac></math>"},{"key":"B","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><msqrt><mn>3</mn></msqrt></math>"},{"key":"C","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mfrac><mn>3</mn><mn>2</mn></mfrac></math>"},{"key":"D","text":"1"}]', '"A"', '<p>sin(π/6) = sin 30° = 1/2.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d11-b1:q005:r1', 'd11-b1', 5, 1, 'mcq', '<p>Giá trị của <math xmlns="http://www.w3.org/1998/Math/MathML"><mrow><mi>cos</mi><mi>π</mi></mrow></math> bằng</p>', '[{"key":"A","text":"0"},{"key":"B","text":"1"},{"key":"C","text":"−1"},{"key":"D","text":"1/2"}]', '"C"', '<p>cos π = cos 180° = −1.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d11-b1:q009:r1', 'd11-b1', 9, 1, 'mcq', '<p>Góc 180° có số đo radian bằng</p>', '[{"key":"A","text":"π/2"},{"key":"B","text":"π"},{"key":"C","text":"2π"},{"key":"D","text":"π/3"}]', '"B"', '<p>180° tương ứng với π radian.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d11-b1:q014:r1', 'd11-b1', 14, 1, 'short', '<p>Tính <math xmlns="http://www.w3.org/1998/Math/MathML"><mrow><mi>cos</mi><mn>0</mn></mrow></math>.</p>', '[]', '"1"', '<p>cos 0 = 1.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d11-b1:q020:r1', 'd11-b1', 20, 1, 'tf', '<p>Xét tính đúng sai của các khẳng định sau.</p>', '[{"key":"a","text":"sin 0 = 0."},{"key":"b","text":"cos 0 = 0."},{"key":"c","text":"sin(π/2) = 1."},{"key":"d","text":"tan(π/4) = 1."}]', '[true,false,true,true]', '<p>cos 0 = 1 nên ý b sai. Các giá trị ở a, c, d đều đúng.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d11-b2:q002:r1', 'd11-b2', 2, 1, 'mcq', '<p>Nghiệm của phương trình <math xmlns="http://www.w3.org/1998/Math/MathML"><mrow><mi>sin</mi><mi>x</mi><mo>=</mo><mn>0</mn></mrow></math> là (k ∈ ℤ)</p>', '[{"key":"A","text":"x = kπ"},{"key":"B","text":"x = π/2 + kπ"},{"key":"C","text":"x = π/4 + kπ"},{"key":"D","text":"x = π/2 + 2kπ"}]', '"A"', '<p>sin x = 0 khi và chỉ khi x = kπ, k nguyên.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d11-b2:q006:r1', 'd11-b2', 6, 1, 'mcq', '<p>Nghiệm của phương trình <math xmlns="http://www.w3.org/1998/Math/MathML"><mrow><mi>cos</mi><mi>x</mi><mo>=</mo><mn>1</mn></mrow></math> là (k ∈ ℤ)</p>', '[{"key":"A","text":"x = π + 2kπ"},{"key":"B","text":"x = π/2 + kπ"},{"key":"C","text":"x = kπ"},{"key":"D","text":"x = 2kπ"}]', '"D"', '<p>cos x = 1 khi và chỉ khi x = 2kπ, k nguyên.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d11-b2:q010:r1', 'd11-b2', 10, 1, 'short', '<p>Phương trình sin x = 0 có bao nhiêu nghiệm thuộc đoạn [0; 2π]?</p>', '[]', '"3"', '<p>Các nghiệm là 0, π, 2π. Vì khoảng xét là đoạn đóng nên có 3 nghiệm.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d11-b2:q013:r1', 'd11-b2', 13, 1, 'mcq', '<p>Nghiệm của phương trình tan x = 1 là (k ∈ ℤ)</p>', '[{"key":"A","text":"x = π/4 + kπ"},{"key":"B","text":"x = −π/4 + kπ"},{"key":"C","text":"x = kπ"},{"key":"D","text":"x = π/4 + 2kπ"}]', '"A"', '<p>tan x = tan(π/4) khi và chỉ khi x = π/4 + kπ.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d11-b2:q021:r1', 'd11-b2', 21, 1, 'tf', '<p>Xét các khẳng định sau.</p>', '[{"key":"a","text":"x = 0 là nghiệm của sin x = 0."},{"key":"b","text":"x = π là nghiệm của sin x = 0."},{"key":"c","text":"x = π/2 là nghiệm của sin x = 0."},{"key":"d","text":"x = 2π là nghiệm của cos x = 1."}]', '[true,true,false,true]', '<p>sin(π/2) = 1 nên ý c sai. Ba khẳng định còn lại đúng.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d12-b1:q001:r1', 'd12-b1', 1, 1, 'mcq', '<p>Cho hình hộp ABCD.A′B′C′D′. Tổng <math xmlns="http://www.w3.org/1998/Math/MathML"><mrow><mover accent="true"><mi>AB</mi><mo>→</mo></mover><mo>+</mo><mover accent="true"><mi>AD</mi><mo>→</mo></mover><mo>+</mo><mover accent="true"><mi>AA′</mi><mo>→</mo></mover></mrow></math> bằng</p>', '[{"key":"A","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>AC′</mi><mo>→</mo></mover></math>"},{"key":"B","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>A′C</mi><mo>→</mo></mover></math>"},{"key":"C","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>BD′</mi><mo>→</mo></mover></math>"},{"key":"D","text":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><mover accent=\"true\"><mi>AB′</mi><mo>→</mo></mover></math>"}]', '"A"', '<p>Áp dụng quy tắc hình hộp: vectơ AB + vectơ AD + vectơ AA′ = vectơ AC′.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d12-b1:q004:r1', 'd12-b1', 4, 1, 'mcq', '<p>Hai vectơ khác vectơ không và ngược hướng có góc giữa chúng bằng</p>', '[{"key":"A","text":"0°"},{"key":"B","text":"90°"},{"key":"C","text":"180°"},{"key":"D","text":"60°"}]', '"C"', '<p>Hai vectơ ngược hướng có góc bằng 180°.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d12-b1:q006:r1', 'd12-b1', 6, 1, 'short', '<p>Hai vectơ a, b vuông góc với nhau và có độ dài lần lượt là 3 và 4. Tính độ dài a + b.</p>', '[]', '"5"', '<p>|a + b|² = |a|² + |b|² + 2a · b = 9 + 16 = 25, do đó |a + b| = 5.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d12-b1:q010:r1', 'd12-b1', 10, 1, 'mcq', '<p>Cho vectơ a = 2b, với b khác vectơ không. Hai vectơ a và b</p>', '[{"key":"A","text":"Cùng hướng"},{"key":"B","text":"Ngược hướng"},{"key":"C","text":"Vuông góc"},{"key":"D","text":"Không cùng phương"}]', '"A"', '<p>Hệ số 2 dương nên vectơ a và b cùng hướng.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d12-b1:q018:r1', 'd12-b1', 18, 1, 'tf', '<p>Với các vectơ a, b bất kỳ, xét các khẳng định sau.</p>', '[{"key":"a","text":"a + b = b + a."},{"key":"b","text":"a + vectơ không = a."},{"key":"c","text":"2a = a + a."},{"key":"d","text":"|−a| = −|a| luôn đúng."}]', '[true,true,true,false]', '<p>Độ dài không âm; |−a| = |a|. Ý d không đúng với vectơ khác vectơ không.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d12-b2:q002:r1', 'd12-b2', 2, 1, 'mcq', '<p>Trong không gian Oxyz, cho A(1; 2; 3), B(3; 1; 5). Tọa độ vectơ AB là</p>', '[{"key":"A","text":"(2; −1; 2)"},{"key":"B","text":"(−2; 1; −2)"},{"key":"C","text":"(4; 3; 8)"},{"key":"D","text":"(2; 1; 2)"}]', '"A"', '<p>Vectơ AB = (3 − 1; 1 − 2; 5 − 3) = (2; −1; 2).</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d12-b2:q005:r1', 'd12-b2', 5, 1, 'mcq', '<p>Độ dài của vectơ a = (1; 2; 2) bằng</p>', '[{"key":"A","text":"5"},{"key":"B","text":"9"},{"key":"C","text":"3"},{"key":"D","text":"√5"}]', '"C"', '<p>|a| = √(1² + 2² + 2²) = 3.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d12-b2:q008:r1', 'd12-b2', 8, 1, 'mcq', '<p>Cho vectơ a = (1; 0; 1), vectơ b = (0; 2; 1). Tính a · b.</p>', '[{"key":"A","text":"0"},{"key":"B","text":"1"},{"key":"C","text":"2"},{"key":"D","text":"3"}]', '"B"', '<p>a · b = 1 × 0 + 0 × 2 + 1 × 1 = 1.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d12-b2:q012:r1', 'd12-b2', 12, 1, 'short', '<p>Tính độ dài của vectơ a = (2; −1; 2).</p>', '[]', '"3"', '<p>|a| = √(4 + 1 + 4) = 3.</p>');
INSERT OR IGNORE INTO questions (id, lesson_id, original_number, revision, kind, prompt, choices, correct, solution) VALUES ('d12-b2:q022:r1', 'd12-b2', 22, 1, 'tf', '<p>Cho A(0; 0; 0), B(1; 2; 3). Xét các khẳng định sau.</p>', '[{"key":"a","text":"Vectơ AB = (1; 2; 3)."},{"key":"b","text":"Vectơ BA = (−1; −2; −3)."},{"key":"c","text":"Trung điểm của AB là (1; 1; 1)."},{"key":"d","text":"Độ dài AB bằng √14."}]', '[true,true,false,true]', '<p>Trung điểm của AB là (1/2; 1; 3/2), nên ý c sai. Các ý còn lại đúng.</p>');
